const $=id=>document.getElementById(id);
let rows=[],settings={},record=null,dirty=false,pending=null;
const params=new URLSearchParams(location.hash.slice(1));let token=params.get('group')||'';const classToken=params.get('class')||'';
function status(message,error=false){$('status').textContent=message;$('status').className='message'+(error?' error':'');}
function initialRows(){return[{time:0,vol:0},...Array.from({length:5},()=>({time:'',vol:''}))];}
function changed(){dirty=true;pending=null;status('未保存の変更があります。「保存して濃度を更新」を押してください。');document.querySelectorAll('[data-concentration]').forEach(e=>e.textContent='—');}
function render(){const body=$('rows');body.replaceChildren();let j=0;rows.forEach((r,i)=>{const tr=document.createElement('tr'),number=document.createElement('td');number.textContent=i===0?'初期':i;tr.append(number);for(const [key,name]of[['time','時間'],['vol','捕集体積']]){const td=document.createElement('td'),input=document.createElement('input');input.type='number';input.min=0;input.step='any';input.value=r[key];input.readOnly=i===0&&key==='time';input.setAttribute('aria-label',`${i+1}行目の${name}`);input.oninput=()=>{rows[i][key]=input.value;changed();};td.append(input);tr.append(td);}const c=document.createElement('td');c.dataset.concentration='';const value=r.time!==''||r.vol!==''?record?.concentrations?.[j++]?.c:null;c.textContent=!dirty&&value!=null?Number(value).toPrecision(4):'—';tr.append(c);const td=document.createElement('td'),remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.disabled=i===0;remove.setAttribute('aria-label',`${i+1}行目を削除`);remove.onclick=()=>{rows.splice(i,1);changed();render();};td.append(remove);tr.append(td);body.append(tr);});}
function draw(){const points=(record?.concentrations||[]).filter(p=>p.c!==null&&Number.isFinite(p.c));if(!points.length){$('plot').innerHTML='<div class="empty">濃度計算に必要な測定点を記録・保存してください。</div>';return;}const W=720,H=280,L=75,B=40,T=25,R=20,xmax=Math.max(1,...points.map(p=>p.t))*1.05,ymin=Math.min(0,...points.map(p=>p.c)),ymax=Math.max(.001,...points.map(p=>p.c))*1.1,x=v=>L+v/xmax*(W-L-R),y=v=>H-B-(v-ymin)/(ymax-ymin)*(H-T-B);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="保存済みの濃度変化グラフ">`;for(let i=0;i<=4;i++){let value=ymin+(ymax-ymin)*i/4,yy=y(value),xx=x(xmax*i/4);svg+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#e0e9e2"/><text x="${L-10}" y="${yy+4}" text-anchor="end" font-size="11" fill="#678276">${Number(value.toPrecision(3))}</text><text x="${xx}" y="${H-15}" text-anchor="middle" font-size="11" fill="#678276">${Math.round(xmax*i/4)}</text>`;}svg+=`<polyline points="${points.map(p=>x(p.t)+','+y(p.c)).join(' ')}" fill="none" stroke="#087e79" stroke-width="2.5"/>`;for(const p of points)svg+=`<circle cx="${x(p.t)}" cy="${y(p.c)}" r="4" fill="#087e79"><title>${p.t} s / ${p.c.toPrecision(4)} mol/L</title></circle>`;$('plot').innerHTML=svg+'</svg>';}
function displayRecord(value){record=value;$('measurement-temp').value=value?.temperature??'';rows=value?.rows?.map(r=>({time:r.time,vol:r.vol}))||initialRows();while(rows.length<6)rows.push({time:'',vol:''});dirty=false;pending=null;render();draw();$('saved').textContent=value?'保存日時：'+new Date(value.created_at).toLocaleString('ja-JP'):'まだ保存されていません。';}
async function load(){if(dirty&&!confirm('未保存の入力を破棄して、班の最新記録を読み込みますか？'))return;try{const data=await LabAPI.rpc('lab_student_open',{p_token:token});settings=data.settings;$('group-label').textContent=data.label;$('timehead').textContent=`時間（${settings.unit}）`;$('volhead').textContent=(settings.input==='total'?'累積体積':'区間の増加体積')+'（mL）';const dl=$('conditions');dl.replaceChildren();for(const[label,value]of[['大気圧',settings.pressure+' Pa'],['反応液の全体積',settings.volume+' mL'],['水蒸気補正',settings.wet?'あり':'なし']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;dl.append(dt,dd);}displayRecord(data.record);$('student-form').hidden=false;$('student-form').disabled=false;status(data.record?.warning||'自分の班の記録を開きました。');}catch(e){status(e.message,true);}}
$('add').onclick=()=>{if(rows.length>=101){status('測定は100行までです。',true);return;}rows.push({time:'',vol:''});changed();render();};
$('reload').onclick=load;
$('submit').onclick=async()=>{const filled=rows.filter(r=>r.time!==''||r.vol!=='');if(filled.some(r=>r.time===''||r.vol==='')){status('入力した行の時間・体積を両方記入してください。',true);return;}const temperature=$('measurement-temp').value;if(temperature===''||!Number.isFinite(Number(temperature))||Number(temperature)<0||Number(temperature)>60){status('測定温度を0～60 ℃で入力してください。',true);$('measurement-temp').focus();return;}if(!pending)pending={id:crypto.randomUUID(),rows:filled,temperature:Number(temperature)};$('student-form').disabled=true;status('サーバーに保存しています…');try{const saved=await LabAPI.rpc('lab_student_save',{p_token:token,p_rows:pending.rows,p_request_id:pending.id,p_temperature:pending.temperature});displayRecord(saved);status(saved.warning||'保存しました。教員もこの記録を確認できます。');}catch(e){status(e.message,true);}finally{$('student-form').disabled=false;}};
$('measurement-temp').oninput=changed;
$('class-entry').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{const joined=await LabAPI.rpc('lab_class_join',{p_token:classToken,p_label:$('entry-label').value.trim(),p_code:$('entry-code').value.trim()});token=joined.token;const url=new URL(location.href);url.hash=new URLSearchParams({group:token}).toString();history.replaceState(null,'',url);$('entry-code').value='';$('class-entry').hidden=true;await load();}catch(error){status(error.message,true);}finally{button.disabled=false;}};
async function openClass(){try{const c=await LabAPI.rpc('lab_class_open',{p_token:classToken});$('class-name').textContent=c.label;$('group-label').textContent=c.label+'：班名と班別コードで入室してください。';$('class-entry').hidden=false;status('自分の班名と班別コードを入力してください。');}catch(e){status(e.message,true);}}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
if(!LabAPI.ready())status('保存・認証の初期設定がまだ完了していません。教員に確認してください。',true);else if(/^[a-f0-9]{64}$/.test(classToken))openClass();else if(!/^[a-f0-9]{64}$/.test(token))status('教員から配布されたクラス共通リンクまたは班専用リンクで開いてください。',true);else load();
